 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 int threshold = _PB_N / 10;

 for (k = 1; k < _PB_N; k++) {
   beta = (1 - alpha * alpha) * beta;
   sum = SCALAR_VAL(0.0);

   #pragma omp parallel if(k > threshold)
   {
     double sum_private = 0.0;

     #pragma omp for simd nowait
     for (i = 0; i < k; i++) {
       sum_private += r[k-i-1] * y[i];
     }

     #pragma omp atomic
     sum += sum_private;

     #pragma omp barrier

     #pragma omp single
     {
       alpha = - (r[k] + sum) / beta;
     }

     #pragma omp for simd
     for (i = 0; i < k; i++) {
       z[i] = y[i] + alpha * y[k-i-1];
     }

     #pragma omp for simd
     for (i = 0; i < k; i++) {
       y[i] = z[i];
     }
   }

   y[k] = alpha;
 }
#pragma endscop
```

